# F4 — multiview-parity fixtures: lock the vendored cooperative backend
# against CRAN multiview 1.0 on frozen inputs, and pin the three deliberate
# divergences documented in inst/PATCHES.cooperative.md (D4/B1 offset
# subsetting in build_predmat, D5/B2 halved-step residual weighting, D6/B3
# lower.limits plumbing). This makes the B4 divergence log testable.
#
# The fixtures live in tests/testthat/fixtures/multiview_parity/ and are
# verified by a SHA-256 manifest (same pattern as fixtures/python_parity/).
# Reference values were generated by CRAN multiview 1.0 itself (see
# generate.R and provenance.json in the fixture directory); running these
# tests needs neither multiview nor Python. Live cross-checks against an
# installed multiview 1.0 run only when the package happens to be available.

.mvparity_fixture_dir <- function() {
  testthat::test_path("fixtures", "multiview_parity")
}

.mvparity_read <- function(name) {
  utils::read.csv(file.path(.mvparity_fixture_dir(), name), stringsAsFactors = FALSE)
}

.mvparity_inputs <- function() {
  readRDS(file.path(.mvparity_fixture_dir(), "inputs.rds"))
}

.mvparity_sha256 <- function(path) {
  sha256sum <- Sys.which("sha256sum")
  if (nzchar(sha256sum)) {
    output <- system2(sha256sum, path, stdout = TRUE, stderr = TRUE)
    return(tolower(strsplit(output[[1L]], "[[:space:]]+")[[1L]][[1L]]))
  }
  shasum <- Sys.which("shasum")
  if (nzchar(shasum)) {
    output <- system2(shasum, c("-a", "256", path), stdout = TRUE, stderr = TRUE)
    return(tolower(strsplit(output[[1L]], "[[:space:]]+")[[1L]][[1L]]))
  }
  NA_character_
}

# Helper: run expr, muffling and collecting warnings (weighted binomial
# fits warn about non-integer successes).
.mvparity_muffled <- function(expr) {
  msgs <- character(0)
  val <- withCallingHandlers(
    expr,
    warning = function(m) {
      msgs <<- c(msgs, conditionMessage(m))
      invokeRestart("muffleWarning")
    }
  )
  list(value = val, warnings = msgs)
}

.mvparity_x_list <- function(inputs) {
  list(a = inputs$view_a, b = inputs$view_b)
}

.mvparity_vendored_fit <- function(inputs, y, family, weights = NULL,
                                   offset = NULL, lambda,
                                   lower.limits = -Inf) {
  .mvparity_muffled(stablr:::.cooperative_backend_fit(
    .mvparity_x_list(inputs), y, family = family, rho = inputs$rho,
    weights = weights, offset = offset, lambda = lambda,
    lower.limits = lower.limits
  ))
}

# Compare a live fit against frozen rows for one engine label:
# coefficients must match to numerical tolerance and the selection
# schedule (nonzero pattern) must match exactly.
.mvparity_check_engine_rows <- function(fit, rows) {
  b <- as.matrix(fit$beta)
  got <- b[cbind(match(rows$feature, rownames(b)), rows$lambda_index)]
  expect_equal(got, rows$coefficient, tolerance = 1e-6,
               info = paste(unique(rows$family), unique(rows$engine)))
  expect_identical(got != 0, rows$selected,
                   info = paste(unique(rows$family), unique(rows$engine)))
}

test_that("multiview-parity fixtures match their SHA-256 manifest", {
  manifest <- readLines(file.path(.mvparity_fixture_dir(), "manifest.sha256"))
  expect_gt(length(manifest), 0L)
  for (line in manifest) {
    parts <- strsplit(line, "  ", fixed = TRUE)[[1L]]
    expect_length(parts, 2L)
    expect_identical(
      .mvparity_sha256(file.path(.mvparity_fixture_dir(), parts[[2L]])),
      tolower(parts[[1L]]),
      info = parts[[2L]]
    )
  }
})

test_that("vendored gaussian backend reproduces CRAN multiview 1.0 (unit weights, no offset)", {
  inputs <- .mvparity_inputs()
  ref <- .mvparity_read("reference_parity_gaussian.csv")
  fit <- .mvparity_vendored_fit(inputs, inputs$y_gaussian, "gaussian",
                                lambda = inputs$lambda_gaussian)
  expect_s3_class(fit$value, "multiview")
  for (engine in unique(ref$engine)) {
    .mvparity_check_engine_rows(fit$value, ref[ref$engine == engine, , drop = FALSE])
  }
})

test_that("vendored binomial backend reproduces CRAN multiview 1.0 (unit weights, no offset)", {
  inputs <- .mvparity_inputs()
  ref <- .mvparity_read("reference_parity_binomial.csv")
  fit <- .mvparity_vendored_fit(inputs, inputs$y_binomial, "binomial",
                                lambda = inputs$lambda_binomial)
  expect_s3_class(fit$value, "multiview")
  for (engine in unique(ref$engine)) {
    .mvparity_check_engine_rows(fit$value, ref[ref$engine == engine, , drop = FALSE])
  }
})

test_that("weighted fits without offset reproduce CRAN multiview 1.0 (B2 must not bite)", {
  inputs <- .mvparity_inputs()
  ref <- .mvparity_read("reference_parity_weighted.csv")
  for (fam in unique(ref$family)) {
    rows <- ref[ref$family == fam, , drop = FALSE]
    is_gaussian <- grepl("^gaussian", fam)
    y <- if (is_gaussian) inputs$y_gaussian else inputs$y_binomial
    lambda <- if (is_gaussian) inputs$lambda_gaussian else inputs$lambda_binomial
    fit <- .mvparity_vendored_fit(inputs, y, sub("_weighted$", "", fam),
                                  weights = inputs$weights_weighted,
                                  lambda = lambda)
    for (engine in unique(rows$engine)) {
      .mvparity_check_engine_rows(fit$value, rows[rows$engine == engine, , drop = FALSE])
    }
  }
})

test_that("B1/D4: vendored build_predmat subsets the offset per fold; upstream 1.0 errors", {
  inputs <- .mvparity_inputs()
  x_list <- .mvparity_x_list(inputs)
  foldid <- inputs$foldid
  offset <- inputs$offset_nonzero
  lambda <- inputs$lambda_gaussian

  # fold fits built exactly like the .mv_cv_multiview fold loop
  outlist <- lapply(sort(unique(foldid)), function(k) {
    which_k <- foldid == k
    .mvparity_muffled(stablr:::.mv_multiview(
      x_list = lapply(x_list, function(m) m[!which_k, , drop = FALSE]),
      y = inputs$y_gaussian[!which_k],
      family = stats::gaussian(), rho = inputs$rho,
      offset = offset[!which_k], lambda = lambda
    ))$value
  })

  predmat <- stablr:::build_predmat(outlist, lambda, x_list, offset, foldid,
                                    "lambda", stats::gaussian())
  ref <- .mvparity_read("reference_b1_predmat_offset.csv")
  got <- predmat[cbind(ref$sample_index, ref$lambda_index)]
  expect_equal(got, ref$prediction, tolerance = 1e-6)

  # independent cross-check: manual fold-wise prediction with correctly
  # subset offsets must reproduce the predmat
  for (k in sort(unique(foldid))) {
    which_k <- foldid == k
    manual <- stats::predict(
      outlist[[k]],
      lapply(x_list, function(m) m[which_k, , drop = FALSE]),
      s = lambda, newoffset = offset[which_k]
    )
    expect_equal(as.vector(predmat[which_k, seq_along(lambda)]),
                 as.vector(as.matrix(manual)),
                 tolerance = 1e-6, info = paste("fold", k))
  }

  # upstream multiview 1.0 self-references `offset_sub` before it exists
  # (R/build_predmat.R:26), so the same call errors upstream
  skip_if_not_installed("multiview", "1.0")
  upstream <- tryCatch(
    multiview:::build_predmat(outlist, lambda, x_list, offset, foldid,
                              "lambda", stats::gaussian()),
    error = function(e) conditionMessage(e)
  )
  expect_true(is.character(upstream),
              info = "upstream build_predmat should fail on an offset input")
  expect_true(grepl("offset_sub", upstream),
              info = paste("unexpected upstream error:", upstream))
})

test_that("B1/D4: cv path with a non-NULL offset completes and matches the frozen cv curve", {
  inputs <- .mvparity_inputs()
  cvfit <- .mvparity_muffled(stablr:::.cooperative_backend_cv(
    .mvparity_x_list(inputs), inputs$y_gaussian, family = "gaussian",
    rho = inputs$rho, foldid = inputs$foldid,
    offset = inputs$offset_nonzero, lambda = inputs$lambda_gaussian
  ))$value
  expect_true(all(c("lambda", "cvm") %in% names(cvfit)))
  ref <- .mvparity_read("reference_b1_cv_offset.csv")
  expect_equal(cvfit$lambda, ref$lambda, tolerance = 1e-8)
  expect_equal(cvfit$cvm, ref$cvm, tolerance = 1e-6)
  expect_false(anyNA(cvfit$cvm))
})

test_that("B2/D5: weighted fit with non-zero offset pins the halved-step residual behavior", {
  inputs <- .mvparity_inputs()
  ref <- .mvparity_read("reference_b2_weighted_offset.csv")

  for (fam in setdiff(unique(ref$family), "binomial_weighted_offset_separating")) {
    rows <- ref[ref$family == fam & ref$engine == "vendored", , drop = FALSE]
    is_gaussian <- grepl("^gaussian", fam)
    y <- if (is_gaussian) inputs$y_gaussian else inputs$y_binomial
    lambda <- if (is_gaussian) inputs$lambda_gaussian else inputs$lambda_binomial
    fit <- .mvparity_vendored_fit(inputs, y, sub("_weighted.*$", "", fam),
                                  weights = inputs$weights_weighted,
                                  offset = inputs$offset_nonzero, lambda = lambda)
    expect_s3_class(fit$value, "multiview")
    expect_false(anyNA(as.matrix(fit$value$beta)))
    .mvparity_check_engine_rows(fit$value, rows)
  }

  # aggressive separating-offset variant (only frozen if both engines
  # completed it at generation time)
  if (any(ref$family == "binomial_weighted_offset_separating")) {
    rows <- ref[ref$family == "binomial_weighted_offset_separating" &
                  ref$engine == "vendored", , drop = FALSE]
    fit <- .mvparity_vendored_fit(inputs, inputs$y_binomial, "binomial",
                                  weights = inputs$weights_weighted,
                                  offset = inputs$offset_separating,
                                  lambda = inputs$lambda_binomial)
    expect_s3_class(fit$value, "multiview")
    .mvparity_check_engine_rows(fit$value, rows)
  }

  # live cross-check against CRAN multiview 1.0 when available
  skip_if_not_installed("multiview", "1.0")
  for (fam in unique(ref$family)) {
    rows <- ref[ref$family == fam & ref$engine == "cran_1_0", , drop = FALSE]
    is_gaussian <- grepl("^gaussian", fam)
    y <- if (is_gaussian) inputs$y_gaussian else inputs$y_binomial
    lambda <- if (is_gaussian) inputs$lambda_gaussian else inputs$lambda_binomial
    offset <- if (fam == "binomial_weighted_offset_separating") {
      inputs$offset_separating
    } else {
      inputs$offset_nonzero
    }
    cran <- .mvparity_muffled(multiview::multiview(
      .mvparity_x_list(inputs), y, family = if (is_gaussian) stats::gaussian() else stats::binomial(),
      rho = inputs$rho, weights = inputs$weights_weighted, offset = offset,
      lambda = lambda
    ))
    .mvparity_check_engine_rows(cran$value, rows)
  }
})

test_that("B3/D6: binding lower.limits are honored and pinned by the vendored fit", {
  inputs <- .mvparity_inputs()
  lower_limits <- rep(-Inf, 2L * inputs$p)
  lower_limits[inputs$p + 2L] <- -0.2  # feature "b2"

  fit <- .mvparity_vendored_fit(inputs, inputs$y_gaussian, "gaussian",
                                lambda = inputs$lambda_gaussian,
                                lower.limits = lower_limits)
  b <- as.matrix(fit$value$beta)
  expect_true(all(b[inputs$p + 2L, ] >= -0.2 - 1e-8),
              info = "lower.limits must clamp the b2 coefficient at -0.2")
  ref <- .mvparity_read("reference_b3_lower_limits.csv")
  for (engine in unique(ref$engine)) {
    .mvparity_check_engine_rows(fit$value, ref[ref$engine == engine, , drop = FALSE])
  }

  # live cross-check against CRAN multiview 1.0 when available
  skip_if_not_installed("multiview", "1.0")
  cran <- .mvparity_muffled(multiview::multiview(
    .mvparity_x_list(inputs), inputs$y_gaussian, family = stats::gaussian(),
    rho = inputs$rho, lambda = inputs$lambda_gaussian,
    lower.limits = lower_limits
  ))
  .mvparity_check_engine_rows(cran$value,
                              ref[ref$engine == "cran_1_0", , drop = FALSE])
})

test_that("provenance records the three deliberate divergences (B4 divergence log)", {
  prov <- paste(readLines(file.path(.mvparity_fixture_dir(), "provenance.json")),
                collapse = "\n")
  expect_true(grepl('"D4_B1"', prov, fixed = TRUE), info = "missing D4/B1 entry")
  expect_true(grepl('"D5_B2"', prov, fixed = TRUE), info = "missing D5/B2 entry")
  expect_true(grepl('"D6_B3"', prov, fixed = TRUE), info = "missing D6/B3 entry")
  expect_true(grepl("multiview", prov), info = "missing reference engine record")
  expect_true(grepl('"version": "1.0"', prov, fixed = TRUE),
              info = "reference engine version must be pinned to 1.0")
})
